@Override
	public void readFromNBT(NBTTagCompound nbt) {
		if(nbt.hasKey("x", Constants.NBT.TAG_INT) && nbt.hasKey("y", Constants.NBT.TAG_INT) && nbt.hasKey("z", Constants.NBT.TAG_INT)) {
